static void bindParameter(PreparedStatement ps, int index, Object value) throws SQLException {
  if (value instanceof Integer i) ps.setInt(index, i);
  else if (value instanceof String s) ps.setString(index, s);
  else if (value instanceof BigDecimal bd) ps.setBigDecimal(index, bd);
  else if (value instanceof LocalDate ld) ps.setDate(index, Date.valueOf(ld));
  else if (value instanceof LocalDateTime ldt) ps.setTimestamp(index, Timestamp.valueOf(ldt));
}

