static int insertAndReturnId(Connection conn, String name, BigDecimal salary) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("INSERT INTO employees (name, salary) VALUES (?,?)", Statement.RETURN_GENERATED_KEYS)) {
    ps.setString(1, name); ps.setBigDecimal(2, salary);
    ps.executeUpdate();
    try (ResultSet keys = ps.getGeneratedKeys()) { keys.next(); return keys.getInt(1); }
  }
}

static void findEmployees(Connection conn, String nameFilter, BigDecimal minSalary) throws SQLException {
  StringBuilder sql = new StringBuilder("SELECT * FROM employees");
  List<Object> params = new ArrayList<>();
  List<String> conditions = new ArrayList<>();
  if (nameFilter != null) { conditions.add("name = ?"); params.add(nameFilter); }
  if (minSalary != null) { conditions.add("salary >= ?"); params.add(minSalary); }
  if (!conditions.isEmpty()) sql.append(" WHERE ").append(String.join(" AND ", conditions));
  try (PreparedStatement ps = conn.prepareStatement(sql.toString())) {
    for (int i = 0; i < params.size(); i++) ps.setObject(i + 1, params.get(i));
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) System.out.println(rs.getString("name")); }
  }
}

